  const bst = (vals) => {
    const heap = [];
    for (const v of vals) {
      let i = 0;
      while (heap[i] != null && i <= 30) i = v < heap[i] ? 2 * i + 1 : 2 * i + 2;
      if (i <= 30) heap[i] = v;
    }
