class Solution {
    public ListNode middleNode(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {     // fast 还能再走两步
            slow = slow.next;                           // 慢指针走一步
            fast = fast.next.next;                      // 快指针走两步
        }
        return slow;                                    // fast 到头时 slow 在中间
    }
}

